// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        HelperBank helper = new HelperBank();
        address helperAddr = address(helper);

        vm.assume(helperAddr != address(0));

        vm.prank(helperAddr);

        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint bal = c.tokenBalance(helperAddr);
        assertTrue(bal == 20);
    }
}

contract HelperBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
